        try (java.sql.Connection conn = Database.getConnection();
             java.sql.PreparedStatement ps = conn.prepareStatement("INSERT INTO inscricoes(id, atividadeId, participanteId, status, criadaEm) VALUES(?, ?, ?, ?, ?)")) {
